package com.bookeat.report.controller;
import com.bookeat.common.response.*;import com.bookeat.security.AppPrincipal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.access.prepost.PreAuthorize;import lombok.RequiredArgsConstructor;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import java.util.*;
@RestController @RequiredArgsConstructor @SecurityRequirement(name="bearerAuth")
public class ReportController {
private final com.bookeat.report.service.ReportService service;
 @GetMapping("/api/v1/admin/dashboard") @PreAuthorize("hasAuthority('REPORT_VIEW')") @Operation(summary="Load database-backed platform totals and 30-day trends",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<Map<String,Object>> op0(@AuthenticationPrincipal AppPrincipal p){return ApiResponse.ok("Load database-backed platform totals and 30-day trends",service.dashboard());}
 @GetMapping("/api/v1/admin/reports/{reportType}") @PreAuthorize("hasAuthority('REPORT_VIEW')") @Operation(summary="Load bounded, scoped report with date filters",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<PageResponse<Map<String,Object>>> op1(@AuthenticationPrincipal AppPrincipal p,@PathVariable com.bookeat.report.enums.ReportType reportType,@Valid @ModelAttribute com.bookeat.report.dto.ReportQuery q){return ApiResponse.ok("Load bounded, scoped report with date filters",service.report(p.userId(),null,reportType,q));}
 @GetMapping("/api/v1/admin/reports/{reportType}/export/{format}") @PreAuthorize("hasAuthority('REPORT_VIEW')") @Operation(summary="Export up to 10000 scoped report rows as CSV or XLSX")
 public org.springframework.http.ResponseEntity<byte[]> export0(@AuthenticationPrincipal AppPrincipal p,@PathVariable com.bookeat.report.enums.ReportType reportType,@PathVariable @Pattern(regexp="csv|xlsx|pdf") String format,@Valid @ModelAttribute com.bookeat.report.dto.ReportQuery q){byte[] bytes=service.export(p.userId(),null,reportType,q,format);return org.springframework.http.ResponseEntity.ok().header("Content-Disposition","attachment; filename=report."+format).header("Cache-Control","no-store").contentType(org.springframework.http.MediaType.parseMediaType(format.equals("csv")?"text/csv;charset=UTF-8":format.equals("pdf")?"application/pdf":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).body(bytes);}
 @GetMapping("/api/v1/owner/restaurants/{restaurantId}/reports/{reportType}") @PreAuthorize("hasRole('OWNER') and hasAuthority('OWNER_REPORT_VIEW')") @Operation(summary="Load bounded, scoped report with date filters",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<PageResponse<Map<String,Object>>> op3(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID restaurantId,@PathVariable com.bookeat.report.enums.ReportType reportType,@Valid @ModelAttribute com.bookeat.report.dto.ReportQuery q){return ApiResponse.ok("Load bounded, scoped report with date filters",service.report(p.userId(),restaurantId,reportType,q));}
 @GetMapping("/api/v1/owner/restaurants/{restaurantId}/reports/{reportType}/export/{format}") @PreAuthorize("hasRole('OWNER') and hasAuthority('OWNER_REPORT_VIEW')") @Operation(summary="Export up to 10000 scoped report rows as CSV or XLSX")
 public org.springframework.http.ResponseEntity<byte[]> export1(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID restaurantId,@PathVariable com.bookeat.report.enums.ReportType reportType,@PathVariable @Pattern(regexp="csv|xlsx|pdf") String format,@Valid @ModelAttribute com.bookeat.report.dto.ReportQuery q){byte[] bytes=service.export(p.userId(),restaurantId,reportType,q,format);return org.springframework.http.ResponseEntity.ok().header("Content-Disposition","attachment; filename=report."+format).header("Cache-Control","no-store").contentType(org.springframework.http.MediaType.parseMediaType(format.equals("csv")?"text/csv;charset=UTF-8":format.equals("pdf")?"application/pdf":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).body(bytes);}
}
